package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;

import java.security.cert.CRL;
import java.security.cert.X509CRL;
import java.time.Instant;
import java.util.Collection;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

import org.bouncycastle.asn1.x500.X500Name;
import org.eclipse.kura.core.testutil.pki.TestCA;
import org.eclipse.kura.core.testutil.pki.TestCA.CRLCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.CertificateCreationOptions;
import org.junit.After;
import org.junit.Test;

public class CrlRollbackTest extends CrlKeystoreServiceTestBase {

    private static final String CRL_PATH = "/ca.crl";
    private static final int DOWNLOADS_PER_CHECK = 3;
    private static final long DOWNLOAD_TIMEOUT_MS = 30_000;

    private final Map<String, Object> crlOptions = new HashMap<>();
    private CrlDistributionServer server;
    private TestCA ca;
    private X509CRL storedCrl;
    private X509CRL publishedCrl;

    @After
    public void closeServer() throws Exception {
        if (this.server != null) {
            this.server.close();
        }
    }

    @Test
    public void olderCrlOfTheSameIssuerDoesNotReplaceTheStoredOne() throws Exception {
        givenTrustedCaPublishingCrls();
        givenCrlPublished(Instant.now().minusSeconds(60));
        givenKeystoreServiceWithCrlManagement(this.crlOptions);
        givenPublishedCrlStored();

        whenCrlIsPublished(Instant.now().minusSeconds(3600));
        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIs(this.storedCrl);
    }

    @Test
    public void newerCrlOfTheSameIssuerReplacesTheStoredOne() throws Exception {
        givenTrustedCaPublishingCrls();
        givenCrlPublished(Instant.now().minusSeconds(3600));
        givenKeystoreServiceWithCrlManagement(this.crlOptions);
        givenPublishedCrlStored();

        whenCrlIsPublished(Instant.now().minusSeconds(60));
        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIs(this.publishedCrl);
    }

    private void givenTrustedCaPublishingCrls() throws Exception {
        this.server = new CrlDistributionServer();
        this.ca = new TestCA(CertificateCreationOptions.builder(new X500Name("CN=Test CA")).build());

        givenTrustedCertificate(this.ca.getCertificate());

        this.crlOptions.put("crl.urls", new String[] { this.server.url(CRL_PATH) });
        this.crlOptions.put("crl.check.interval", 1L);
        this.crlOptions.put("crl.check.interval.time.unit", "SECONDS");
        this.crlOptions.put("crl.update.interval", 1L);
        this.crlOptions.put("crl.update.interval.time.unit", "SECONDS");
    }

    private void givenCrlPublished(final Instant thisUpdate) throws Exception {
        whenCrlIsPublished(thisUpdate);
    }

    private void givenPublishedCrlStored() throws Exception {
        whenCrlIsDownloadedRepeatedly();

        this.storedCrl = this.publishedCrl;
        thenServedCrlIs(this.storedCrl);
    }

    private void whenCrlIsPublished(final Instant thisUpdate) throws Exception {
        this.publishedCrl = this.ca.generateCRL(CRLCreationOptions.builder().withStartDate(Date.from(thisUpdate))
                .withEndDate(Date.from(Instant.now().plusSeconds(3600))).build());
        this.server.publish(CRL_PATH, this.publishedCrl);
    }

    private void whenCrlIsDownloadedRepeatedly() throws Exception {
        this.server.awaitDownloads(CRL_PATH, DOWNLOADS_PER_CHECK, DOWNLOAD_TIMEOUT_MS);
    }

    private void thenServedCrlIs(final X509CRL expected) throws Exception {
        final Collection<CRL> crls = this.keystoreService.getCRLs();

        assertEquals(1, crls.size());
        assertEquals(expected, crls.iterator().next());
        assertEquals(1, this.keystoreService.getCRLStore().getCRLs(null).size());
    }
}
